// pyfloat.mjs
// Emulates CPython's float() parsing and repr()/str() formatting so that
// numeric behavior matches the original Python program bit-for-bit.

const DIGIT_PART = String.raw`\d(?:_?\d)*`;
const FLOAT_RE = new RegExp(
  String.raw`^\s*[+-]?(?:(?:${DIGIT_PART}(?:\.${DIGIT_PART}?)?|\.${DIGIT_PART})(?:[eE][+-]?${DIGIT_PART})?|inf(?:inity)?|nan)\s*$`,
  'i',
);

// Parse a string the way Python's float() does.
// Returns the parsed number, or null when Python would raise ValueError.
export function parsePythonFloat(text) {
  if (!FLOAT_RE.test(text)) return null;
  const cleaned = text.trim().replace(/_/g, '');
  if (/nan/i.test(cleaned)) return NaN;
  const infMatch = /^([+-]?)inf/i.exec(cleaned);
  if (infMatch) return infMatch[1] === '-' ? -Infinity : Infinity;
  return Number(cleaned);
}

// Split a finite JS number into its shortest round-trip decimal digits and
// the decimal exponent of the leading digit (adjusted exponent).
function shortestParts(x) {
  const s = String(x);
  let digits;
  let adjexp;
  const eIdx = s.indexOf('e');
  if (eIdx !== -1) {
    const mantissa = s.slice(0, eIdx);
    adjexp = parseInt(s.slice(eIdx + 1), 10);
    digits = mantissa.replace('.', '');
  } else if (s.includes('.')) {
    const dot = s.indexOf('.');
    const intPart = s.slice(0, dot);
    const fracPart = s.slice(dot + 1);
    if (intPart !== '0') {
      adjexp = intPart.length - 1;
      digits = intPart + fracPart;
    } else {
      const leadZeros = /^0*/.exec(fracPart)[0].length;
      adjexp = -(leadZeros + 1);
      digits = fracPart.slice(leadZeros);
    }
  } else {
    adjexp = s.length - 1;
    digits = s;
  }
  digits = digits.replace(/0+$/, '');
  return { digits, adjexp };
}

// Format a number exactly like Python's repr(float) (same as str(float)).
export function reprPythonFloat(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  const neg = x < 0 || Object.is(x, -0);
  if (x === 0) return neg ? '-0.0' : '0.0';

  const { digits, adjexp } = shortestParts(Math.abs(x));
  const sign = neg ? '-' : '';

  if (adjexp >= -4 && adjexp < 16) {
    // Fixed-point notation; integral values keep a trailing ".0".
    if (adjexp >= 0) {
      if (digits.length > adjexp + 1) {
        return sign + digits.slice(0, adjexp + 1) + '.' + digits.slice(adjexp + 1);
      }
      return sign + digits + '0'.repeat(adjexp + 1 - digits.length) + '.0';
    }
    return sign + '0.' + '0'.repeat(-adjexp - 1) + digits;
  }
  // Scientific notation; exponent always signed and at least two digits.
  const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
  const expSign = adjexp < 0 ? '-' : '+';
  const expDigits = String(Math.abs(adjexp)).padStart(2, '0');
  return sign + mantissa + 'e' + expSign + expDigits;
}

// decimal.mjs
// Minimal reimplementation of Python's decimal.Decimal covering exactly what
// the original program needs: construction from a string, exact division by
// 2 under the default context (28 significant digits, ROUND_HALF_EVEN), and
// Python's str(Decimal) formatting.
//
// A finite value is stored as sign ('-' or ''), a coefficient digit string
// (no leading zeros, at least '0'), and a base-10 exponent, mirroring
// Decimal's (sign, digits, exponent) triple.

// Multiply a decimal digit string by 5 (string-based to stay exact for
// coefficients beyond 2^53).
function mul5(digits) {
  let carry = 0;
  let out = '';
  for (let i = digits.length - 1; i >= 0; i--) {
    const v = (digits.charCodeAt(i) - 48) * 5 + carry;
    out = String.fromCharCode(48 + (v % 10)) + out;
    carry = Math.floor(v / 10);
  }
  if (carry > 0) out = String.fromCharCode(48 + carry) + out;
  return out;
}

export class PyDecimal {
  constructor(sign, digits, exponent, special = null) {
    this.sign = sign;
    this.digits = digits;
    this.exponent = exponent;
    this.special = special; // null, 'nan', or 'inf'
  }

  // Mirrors Decimal(str): accepts fixed/scientific notation plus
  // 'nan'/'inf'/'infinity' (case-insensitive, optional sign).
  static fromString(text) {
    const m = /^([+-]?)(?:(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?|(inf(?:inity)?|nan))$/i.exec(text.trim());
    if (!m || (m[2] === undefined && !m[5]) || (m[2] !== undefined && m[2] === '' && (m[3] === undefined || m[3] === ''))) {
      throw new Error(`Invalid decimal literal: ${text}`);
    }
    const sign = m[1] === '-' ? '-' : '';
    if (m[5]) {
      return new PyDecimal(sign, '0', 0, m[5].toLowerCase().startsWith('nan') ? 'nan' : 'inf');
    }
    const intPart = m[2] || '';
    const fracPart = m[3] || '';
    const expPart = m[4] ? parseInt(m[4], 10) : 0;
    let digits = (intPart + fracPart).replace(/^0+/, '');
    if (digits === '') digits = '0';
    return new PyDecimal(sign, digits, expPart - fracPart.length);
  }

  // Exact halving, matching Decimal('x') / 2 in the default context.
  // Coefficients coming from float repr have at most 17 significant digits,
  // so the exact result (at most 18 digits) always fits the 28-digit
  // context precision and no rounding ever occurs.
  divBy2() {
    if (this.special) return new PyDecimal(this.sign, '0', 0, this.special);
    // Ideal exponent of a / b is exp(a) - exp(b); here exp(2) = 0.
    const idealExp = this.exponent;
    if (this.digits === '0') {
      return new PyDecimal(this.sign, '0', idealExp);
    }
    // x / 2 == (x * 5) / 10
    let digits = mul5(this.digits);
    let exp = this.exponent - 1;
    // Strip trailing zeros, but never past the ideal exponent.
    while (exp < idealExp && digits.endsWith('0')) {
      digits = digits.slice(0, -1);
      exp += 1;
    }
    return new PyDecimal(this.sign, digits, exp);
  }

  // Reproduces Python's str(Decimal).
  toString() {
    if (this.special === 'nan') return this.sign + 'NaN';
    if (this.special === 'inf') return this.sign + 'Infinity';
    const { digits, exponent } = this;
    const adjexp = exponent + digits.length - 1;
    let body;
    if (exponent <= 0 && adjexp >= -6) {
      // Fixed-point notation.
      if (exponent === 0) {
        body = digits;
      } else {
        const point = digits.length + exponent;
        body = point > 0
          ? digits.slice(0, point) + '.' + digits.slice(point)
          : '0.' + '0'.repeat(-point) + digits;
      }
    } else {
      // Scientific notation.
      const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
      body = mantissa + 'E' + (adjexp < 0 ? '-' : '+') + Math.abs(adjexp);
    }
    return this.sign + body;
  }
}

// money.mjs
// Reimplements the behavior of moneyed.Money as observed through the
// reference program: the amount is stored as Decimal(str(amount)) and
// division returns a new Money with the exact decimal quotient.

import { PyDecimal } from './decimal.mjs';
import { reprPythonFloat } from './pyfloat.mjs';
import { CURRENCY_CODES } from './currencies.mjs';

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'CurrencyDoesNotExist';
  }
}

// Currency lookup is case-insensitive on the ISO-style 3-letter code.
export function getCurrency(code) {
  const upper = String(code).toUpperCase();
  if (!CURRENCY_CODES.has(upper)) {
    throw new CurrencyDoesNotExist(upper);
  }
  return upper;
}

export class Money {
  constructor(amount, currency) {
    // moneyed: amount = Decimal(str(amount)) for non-Decimal input.
    this.amount = PyDecimal.fromString(reprPythonFloat(amount));
    this.currency = getCurrency(currency);
  }

  static fromDecimal(decimalAmount, currency) {
    const m = Object.create(Money.prototype);
    m.amount = decimalAmount;
    m.currency = currency;
    return m;
  }

  // moneyed: __truediv__ -> Money(self.amount / other, self.currency)
  divide(n) {
    if (n !== 2) {
      throw new Error('Only division by 2 is supported');
    }
    return Money.fromDecimal(this.amount.divBy2(), this.currency);
  }
}

