      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const inlineValue = eq === -1 ? undefined : token.slice(eq + 1);
      const resolved = resolveLong(name);
      if (resolved === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (resolved === '--help') {
        process.stdout.write(helpText(prog));
        process.exit(0);
      }
      const dest = resolved.slice(2);
      let value;
      if (inlineValue !== undefined) {
        value = inlineValue;
        i += 1;
      } else if (i + 1 < argv.length && looksLikeValue(argv[i + 1])) {
        value = argv[i + 1];
