  if (values.amount === undefined) missing.push('--amount');
  if (values.currency === undefined) missing.push('--currency');
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }
