import { basename } from 'node:path';
import { parseArgs } from './argparse.mjs';
import { Money, CurrencyDoesNotExist } from './money.mjs';

const prog = basename(process.argv[1] || 'test6.mjs');
const args = parseArgs(process.argv.slice(2), prog);

// 创建Money对象
let m;
try {
  m = new Money(args.amount, args.currency);
} catch (err) {
  if (err instanceof CurrencyDoesNotExist) {
    // Python dies with an uncaught moneyed.classes.CurrencyDoesNotExist
    // traceback on stderr and exit code 1.
    process.stderr.write(`moneyed.classes.CurrencyDoesNotExist: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}

// 除以2
const halved = m.divide(2);
// 打印结果金额
console.log(halved.amount.toString());

